// Throwaway probe: run a ROM with "<frame> <keys_hex>" events, dump the last frame as PPM.
use gba_emu::*;
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let rom = std::fs::read(&args[1]).unwrap();
    let frames: u32 = args[2].parse().unwrap();
    let events: Vec<(u32, u32)> = args[4].split(',').map(|e| {
        let mut p = e.split(':'); (p.next().unwrap().parse().unwrap(), u32::from_str_radix(p.next().unwrap(), 16).unwrap())
    }).collect();
    unsafe {
        emu_init();
        std::ptr::copy_nonoverlapping(rom.as_ptr(), emu_rom_buffer(), rom.len());
        emu_load_rom(rom.len() as i32);
        let mut keys = 0;
        for f in 0..frames {
            for &(at, k) in &events { if at == f { keys = k; } }
            emu_set_keys(keys);
            emu_run_frame();
            emu_audio_samples();
        }
        let px = std::slice::from_raw_parts(emu_framebuffer(), 240 * 160);
        let mut out = b"P6\n240 160\n255\n".to_vec();
        for p in px { out.extend_from_slice(&[*p as u8, (*p >> 8) as u8, (*p >> 16) as u8]); }
        std::fs::write(&args[3], out).unwrap();
    }
}

