// Throwaway probe: replay a key file, at frame N dump PPM + IO regs + VRAM/palette.
use gba_emu::gba::Gba;
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let rom = std::fs::read(&a[1]).unwrap();
    let replay = std::fs::read_to_string(&a[2]).unwrap();
    let target: u32 = a[3].parse().unwrap();
    let out = &a[4];
    let ev: Vec<(u32,u32)> = replay.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()).map(|l| {
        let mut p = l.split_whitespace(); (p.next().unwrap().parse().unwrap(), u32::from_str_radix(p.next().unwrap(),16).unwrap())}).collect();
