    let mut o = b"P6\n240 160\n255\n".to_vec();
    for p in px.iter() { o.extend_from_slice(&[*p as u8, (*p>>8) as u8, (*p>>16) as u8]); }
    std::fs::write(format!("{out}.ppm"), o).unwrap();
    let mut s = String::new();
    for off in (0..0x56).step_by(2) { s += &format!("{:03X}: {:04X}\n", off, g.bus.read16(0x0400_0000+off)); }
    std::fs::write(format!("{out}.io"), s).unwrap();
    std::fs::write(format!("{out}.vram"), &g.bus.ppu.vram).unwrap();
    std::fs::write(format!("{out}.pal"), &g.bus.ppu.palette).unwrap();
}
